INSERT INTO `categories` (`categoryid`, `parentid`, `title`, `description`, `meta_title`, `meta_keywords`, `meta_description`, `products`, `products_global`, `subcategories`, `enabled`, `orderby`, `cleanurl`) VALUES
(8, 0, 'All products', '<h2>Shop Online for All products</h2>\r\n\r\n<p>pagination and sort by don&#39;t refresh page.</p>\r\n\r\n<p>Left filter accepts 150 products very fast.</p>\r\n\r\n<p>Cool, fast and nice.</p>\r\n', 'All products', 'testtest', 'test', 150, 150, 0, 1, 44, 'all-products'),
(25, 0, 'Clothing', '<h2>Shop Online for Clothing</h2>\r\n\r\n<p>Add to your wardrobe with a collection of stylish apparel for every occasion. You can opt for a variety of t-shirts,&nbsp;</p>\r\n\r\n<p><strong>shirts</strong>,&nbsp;<strong>polo t-shirts</strong>, jeans, trousers,&nbsp;tracksuits, ethnic wear including kurtas,</p>\r\n\r\n<p>pyjamas and sherwanis as well as smart winter wear.</p>\r\n', '', '', '', 50, 100, 5, 1, 11, 'Clothing'),
(26, 25, 'T-shirts', '<p>Artists worldwide create cool mens&nbsp;<em>t</em>-<em>shirt</em>&nbsp;designs every day... shop for your favorites!</p>\r\n', '', '', '', 10, 10, 0, 1, 0, 'T-shirts'),
(27, 25, 'Topwear', '<p>Our&nbsp;<em>top wear</em>&nbsp;range consists of quick-drying garments with extreme breathability for outstanding ventilation and moisture transport to keep you dry and fresh.</p>\r\n', '', '', '', 10, 10, 0, 1, 10, 'Topwear'),
(28, 25, 'Bottomwear', '<p>Shop from a huge range of fitted handloom pants to floral block printed flared skirts at Fashor.</p>\r\n\r\n<p>Buy ethnic&nbsp;<em>bottom wear</em>&nbsp;for kurtis online</p>\r\n', '', '', '', 10, 10, 0, 1, 22, 'Bottomwear'),
(29, 25, 'Footwear', '<p><em>Footwear</em>&nbsp;- The leading online destination for men&#39;s contemporary fashion and streetwear.</p>\r\n\r\n<p>Shop at our store and also enjoy the best in daily editorial content.</p>\r\n', '', '', '', 10, 10, 0, 1, 33, 'Footwear'),
(30, 25, 'Accessories', '<p>Sunglasses. Shop Now. Shop Watches. Watches. Shop Now. Shop Bags. Bags. Shop Now.</p>\r\n\r\n<p>Shop Unique and Fun&nbsp;<em>Accessories</em>. Shop Watches. Watches.</p>\r\n', '', '', '', 10, 10, 0, 1, 44, 'Accessories'),
(31, 0, 'Electronics', '<h2>Shop Online for Electronics</h2>\r\n\r\n<p>Shop online at Best Buy for an incredible selection of electronics,</p>\r\n\r\n<p>or check out a Best&nbsp;<em>Buy electronics</em>store near you.</p>\r\n', '', '', '', 50, 100, 5, 1, 22, 'Electronics'),
(32, 31, 'Phones', '<p>Last chance for Holiday Deals! Special deals on the latest cell&nbsp;<em>phones</em>&nbsp;and smartphones.</p>\r\n\r\n<p>Get FREE SHIPPING on&nbsp;<em>phones</em>&nbsp;and devices with new activations.</p>\r\n', '', '', '', 10, 10, 0, 1, 0, 'Phones'),
(33, 31, 'TV', '<p><em>V</em>&nbsp;with channels available through Freeview Play. Freeview ... Live&nbsp;<em>TV</em>,</p>\r\n\r\n<p>catch up and on demand all together in one place.</p>\r\n\r\n<p>T&amp;Cs apply.&nbsp;<em>Buy</em>&nbsp;FreeviewPlay&nbsp;<em>TVs</em>.</p>\r\n', '', '', '', 10, 10, 0, 1, 11, 'TV'),
(34, 31, 'Tablets', '<p>Explore our full line of&nbsp;<em>tablets</em>, including the Samsung TabProS,</p>\r\n\r\n<p>&nbsp;and kid-friendly<em>tablets</em>. Find the perfect&nbsp;<em>tablet</em>&nbsp;for you and your family.</p>\r\n', '', '', '', 10, 10, 0, 1, 22, 'Tablets'),
(35, 31, 'Games Consoles', '<p>Online Shopping and Auction Site with a Massive Range of Second Hand &amp; Used Goods.</p>\r\n\r\n<p>Buy Online with Confidence from Cash Converters.</p>\r\n', '', '', '', 10, 10, 0, 1, 33, 'Games-Consoles'),
(36, 31, 'Laptops', '<p>Shop&nbsp;<em>Laptops</em>&nbsp;at Walmart.com and find popular brands including Dell, HP, Samsung,</p>\r\n\r\n<p>Apple and Acer. Save money. Live better.</p>\r\n', '', '', '', 10, 10, 0, 1, 44, 'Laptops'),
(37, 0, 'Jewelry', '<h2>Shop Online for Jewelry</h2>\r\n\r\n<p>If you&#39;re not sure&nbsp;how to buy jewelry for men, or undecided on the cut of diamond you want for your engagement ring,</p>\r\n\r\n<p>you can find the perfect gift at Sears. Whether you&#39;re shopping for a special occasion,</p>\r\n\r\n<p>surprising a loved one with an everyday present or picking out something special for yourself,</p>\r\n\r\n<p>you&#39;ll find just the right piece of jewelry for any situation.</p>\r\n', '', '', '', 50, 100, 5, 1, 20, 'Jewelry'),
(38, 37, 'Rings', '<p>Buy&nbsp;<em>Rings</em>&nbsp;online at the Official&nbsp;store.</p>\r\n\r\n<p>Find the perfect&nbsp;<em>ring</em>&nbsp;to complement your unique style.</p>\r\n', '', '', '', 10, 10, 0, 1, 0, 'Rings'),
(39, 37, 'Earrings', '<p>You&#39;ve searched for&nbsp;<em>Earrings</em>! Etsy has thousands of unique options to choose from,</p>\r\n\r\n<p>like handmade goods, vintage finds, and one-of-a-kind gifts</p>\r\n', '', '', '', 10, 10, 0, 1, 11, 'Earrings'),
(40, 37, 'Bracelets', '<p>You&#39;ve searched for&nbsp;<em>Bracelets</em>! Etsy has thousands of unique options to choose from, like handmade goods,</p>\r\n\r\n<p>vintage finds, and one-of-a-kind gifts.</p>\r\n', '', '', '', 10, 10, 0, 1, 22, 'Bracelets'),
(41, 37, 'Necklaces', '<p><em>Buy</em>&nbsp;fashionable&nbsp;<em>necklaces</em>&nbsp;from Pilgrim. The jewelry in Danish design comes in silver and gold.</p>\r\n\r\n<p>All pieces are handmade. Order online!</p>\r\n', '', '', '', 10, 10, 0, 1, 33, 'Necklaces'),
(42, 37, 'Beads', '<p>A&nbsp;<em>bead</em>&nbsp;is a small, decorative object that is formed in a variety of shapes</p>\r\n\r\n<p>and sizes of a material such as stone, bone, shell, glass, plastic.</p>\r\n', '', '', '', 10, 10, 0, 1, 44, 'Beads');
