(229, 703, 'SKU3657', 2, 'GCDS-Gold-Plated-Logo-Hoop-Earrings', 'GCDS Gold-Plated Logo Hoop Earrings', '<p>Statement-making earrings from streetwear label GCDS. Topped with logo text detailing and finished with a secure closure.</p>\r\n\r\n<p><strong>Content + Care</strong><br />\r\n- Gold-plated metal<br />\r\n- Wipe clean</p>\r\n', '', 129, 79.00, 0.00, 1000, 0, 0, '1', 0, 1545988991, 0, 0, 0, '', '', ''),
(230, 706, 'SKU9358', 4, 'The-Boyscouts-Trail-Pin-Sterling-Silver-Earrings', 'The Boyscouts Trail Pin Sterling Silver Earrings', '<p>Sleek + minimalist earrings from The Boyscouts with a unique curved shape. Complete with a post back closure.</p>\r\n\r\n<p><strong>Content + Care</strong><br />\r\n- Sterling silver<br />\r\n- Wipe clean</p>\r\n', '', 125, 95.00, 0.00, 1000, 0, 0, '1', 0, 1545989105, 0, 0, 0, '', '', ''),
(231, 708, 'SKU547', 4, 'The-Boyscouts-Twist-Hoop-Earrings', 'The Boyscouts Twist Hoop Earrings', '<p>An update on the classic hoop earrings from The Boyscouts. Sleek silver silhouette with an open construction and complete with a twist detail.</p>\r\n\r\n<p><strong>Content + Care</strong><br />\r\n- Mixed metals<br />\r\n- Wipe clean</p>\r\n', '', 139, 199.00, 0.00, 1000, 0, 0, '1', 0, 1545989610, 0, 0, 0, '', '', ''),
(232, 710, 'SKU336', 3, 'The-Boyscouts-Phase-S-Sterling-Silver-Earrings', 'The Boyscouts Phase S Sterling Silver Earrings', '<p>Elegant + minimalist earrings from The Boyscouts featuring a hoop silhouette. Complete with a post-back closure.</p>\r\n\r\n<p><strong>Content + Care</strong><br />\r\n- Sterling silver<br />\r\n- Wipe clean</p>\r\n', '', 135, 115.00, 0.00, 1000, 0, 0, '1', 0, 1545989802, 1, 0, 0, '', '', ''),
(233, 716, 'SKU5789', 3, 'Estella-Bartlett-Rhinestone-Gold-Plated-Hoop-Earrings', 'Estella Bartlett Rhinestone Gold-Plated Hoop Earrings', '<p>Rhinestone gold plated hoop earrings from British jewellery label Estella Bartlett. Tiny hoops get the luxe treatment with stones at the front. With a hinged closure.</p>\r\n\r\n<p><strong>Content + Care</strong><br />\r\n- Mixed metals<br />\r\n- Wipe Clean<br />\r\n- Pierced earrings cannot be returned or exchanged due to hygiene reasons</p>\r\n\r\n<p><strong>Size</strong><br />\r\n- Drop: 1cm</p>\r\n', '', 39, 29.00, 0.00, 1000, 0, 0, '1', 0, 1545989942, 0, 0, 0, '', '', ''),
(234, 719, 'SKU754', 4, 'Five-And-Two-Jewelry-Meredith-Gold-Plated-Hoop-Earrings', 'Five And Two Jewelry Meredith Gold-Plated Hoop Earrings', '<p>Essential chain look earrings in a hoop silhouette from Five And Two Jewelry. Open style finished with post back closures.</p>\r\n\r\n<p><strong>Content + Care</strong><br />\r\n- Gold-plated stainless steel<br />\r\n- Wipe clean</p>\r\n\r\n<p><strong>Size</strong><br />\r\n- 8 mm</p>\r\n', '', 79, 69.00, 0.00, 1000, 0, 0, '1', 0, 1545990085, 0, 0, 0, '', '', ''),
(235, 721, 'SKU4675', 3, 'Five-And-Two-Jewelry-Alexa-Gold-Plated-Pendant-Necklace', 'Five And Two Jewelry Alexa Gold-Plated Pendant Necklace', '<p>Starburst pendant necklace from Five And Two Jewelry. Features a gold-tone construction with a thin chain + complete with an adjustable clasp closure.</p>\r\n\r\n<p><strong>Content + Care</strong><br />\r\n- 16k gold-plated metals<br />\r\n- Wipe clean</p>\r\n\r\n<p><strong>Size</strong><br />\r\n- Length: 44.5 cm<br />\r\n- Extender: 5 cm</p>\r\n', '', 89, 69.00, 0.00, 1000, 0, 0, '1', 0, 1545990465, 1, 0, 0, '', '', ''),
(236, 723, 'SKU335', 4, 'Five-And-Two-Jewelry-Victoria-Gold-Plated-Charm-Necklace', 'Five And Two Jewelry Victoria Gold-Plated Charm Necklace', '<p>Charm pendant necklace from Five And Two Jewelry. Features a gold-plated construction with an adjustable length chain.</p>\r\n\r\n<p><strong>Content + Care</strong><br />\r\n- Gold-plated mixed metals<br />\r\n- Wipe clean</p>\r\n\r\n<p><strong>Size</strong><br />\r\n- Length: 44.5 cm<br />\r\n- Extender: 5 cm</p>\r\n', '', 79, 59.00, 0.00, 1000, 0, 0, '1', 0, 1545997982, 0, 0, 0, '', '', ''),
(237, 726, 'SKU2353', 3, 'Five-And-Two-Jewelry-Celeste-Gold-Plated-Charm-Necklace', 'Five And Two Jewelry Celeste Gold-Plated Charm Necklace', '<p><strong>Content + Care</strong><br />\r\n- Gold-placed brass, copper, CZ<br />\r\n- Wipe clean</p>\r\n\r\n<p><strong>Size</strong><br />\r\n- Length: 44.5 cm<br />\r\n- Extender: 5 cm</p>\r\n', '', 109, 89.00, 0.00, 1000, 0, 0, '1', 0, 1545999412, 0, 0, 0, '', '', ''),
(238, 728, 'SKU464', 4, 'Alex-Monroe-Baby-Bee-Necklace', 'Alex Monroe Baby Bee Necklace', '<p>Sweet little bee necklace from London-based jewellery designer Alex Monroe. Features a bee pendant accent + complete with an adjustable clasp closure.</p>\r\n\r\n<p><strong>Content + Care</strong><br />\r\n- Mixed metals<br />\r\n- Wipe clean</p>\r\n\r\n<p><strong>Size</strong><br />\r\n- Pendant size: 2.5 cm x 1.4 cm</p>\r\n', '', 229, 0.00, 259.00, 1000, 0, 0, '1', 0, 1545999607, 0, 0, 0, '', '', ''),
(239, 731, 'SKU3536', 3, 'Five-And-Two-Jewelry-Peyton-Gold-Plated-Necklace', 'Five And Two Jewelry Peyton Gold-Plated Necklace', '<p>Double layer necklace from Cali-based Five And Two Jewelry. Gold chain look adorned with a mini dog tag pendant. Finished with an adjustable clasp closure.</p>\r\n\r\n<p><strong>Content + Care</strong><br />\r\n- Gold-plated metals<br />\r\n- Wipe clean</p>\r\n', '', 129, 99.00, 0.00, 1000, 0, 0, '1', 0, 1546000536, 0, 1, 0, '', '', ''),
(240, 734, 'SKU1355', 4, 'Five-And-Two-Jewelry-Penelope-Gold-Plated-Toggle-Necklace', 'Five And Two Jewelry Penelope Gold-Plated Toggle Necklace', '<p>Gold layering necklace from Cali-based Five And Two Jewelry. Adorned with a pendant and finished with a toggle closure.</p>\r\n\r\n<p><strong>Content + Care</strong><br />\r\n- Gold-plated metals<br />\r\n- Wipe clean</p>\r\n', '', 109, 89.00, 0.00, 1000, 0, 0, '1', 0, 1546000769, 0, 0, 0, '', '', ''),
(241, 738, 'SKU366', 2, 'Mirabelle-Robin-Charm-Gold-Plated-Necklace', 'Mirabelle Robin Charm Gold-Plated Necklace', '<p>Find the song in your heart with this British-made gold-tone necklace from jewellery label Mirabelle. Features a robin charm to signify growth + renewal. Finished with a clasp closure.</p>\r\n\r\n<p><strong>Content + Care</strong><br />\r\n- Gold-plated brass<br />\r\n- Wipe clean</p>\r\n\r\n<p><strong>Size</strong><br />\r\n- Chain length: 45 cm<br />\r\n- Pendant: 1 cm</p>\r\n', '', 109, 89.00, 0.00, 1000, 0, 0, '1', 0, 1546003059, 0, 0, 0, '', '', ''),
(242, 741, 'SKU7632', 4, 'Five-And-Two-Jewelry-Ash-Gold-Plated-Necklace', 'Five And Two Jewelry Ash Gold-Plated Necklace', '<p>Simple gold necklace from Cali-based Five And Two Jewelry that&#39;s perfect for layering. Wear as a necklace or a double wrap bracelet. Finished with a clasp closure.</p>\r\n\r\n<p><strong>Content + Care</strong><br />\r\n- Gold-plated metal<br />\r\n- Wipe clean</p>\r\n', '', 109, 89.00, 0.00, 1000, 0, 0, '1', 0, 1546003218, 0, 1, 0, '', '', ''),
(243, 744, 'SKU2753', 3, 'Mirabelle-Sitting-Cat-Charm-Gold-Plated-Necklace', 'Mirabelle Sitting Cat Charm Gold-Plated Necklace', '<p>British-made necklace from jewellery label Mirabelle with a gold-plated construction. Features a sitting cat charm + finished with a clasp closure.</p>\r\n\r\n<p><strong>Content + Care</strong><br />\r\n- Gold-plated brass<br />\r\n- Wipe clean</p>\r\n\r\n<p><strong>Size</strong><br />\r\n- Chain length: 45 cm</p>\r\n', '', 109, 89.00, 0.00, 1000, 0, 0, '1', 0, 1546003392, 0, 0, 0, '', '', ''),
(244, 747, 'SKU753', 4, 'Rachel-Jackson-London-Rave-Behave-Gold-Pendant-Necklace', 'Rachel Jackson London Rave, Behave Gold Pendant Necklace', '<p>Reversible pendant necklace by London-based jewellery designer Rachel Jackson topped with cheeky slogan engraving. Gold plated construction finished with an adjustable length chain.</p>\r\n\r\n<p><strong>Content + Care</strong><br />\r\n- Gold-plated metal<br />\r\n- Wipe clean</p>\r\n\r\n<p><strong>Size</strong><br />\r\n- Pendant: 2 cm</p>\r\n', '', 139, 89.00, 0.00, 1000, 0, 0, '1', 0, 1546003712, 0, 0, 0, '', '', ''),
